class Solution {
  public int countSequences(int[] nums, long k) {
    int[] target = new int[3];
    int[] primes = {2, 3, 5};
    long rest = k;
    for (int i = 0; i < 3; i++)
      while (rest % primes[i] == 0) {
        rest /= primes[i];
        target[i]++;
      }
    if (rest != 1) return 0;
    int n = nums.length, OFF = 2 * n + 1, W = 2 * OFF + 1;
    java.util.HashMap<Integer, Long> cur = new java.util.HashMap<>();
    cur.put(encode(0, 0, 0, OFF, W), 1L);
    for (int x : nums) {
      int[] d = new int[3];
      int v = x;
      for (int i = 0; i < 3; i++)
        while (v % primes[i] == 0) {
          v /= primes[i];
          d[i]++;
        }
      java.util.HashMap<Integer, Long> next = new java.util.HashMap<>();
      for (java.util.Map.Entry<Integer, Long> e : cur.entrySet()) {
        int key = e.getKey();
        int c = key % W - OFF, b = key / W % W - OFF, a = key / W / W - OFF;
        for (int sign = -1; sign <= 1; sign++) {
          int nk = encode(a + sign * d[0], b + sign * d[1], c + sign * d[2], OFF, W);
          next.merge(nk, e.getValue(), Long::sum);
        }
      }
      cur = next;
    }
    return (int) (long) cur.getOrDefault(encode(target[0], target[1], target[2], OFF, W), 0L);
  }

  private static int encode(int a, int b, int c, int off, int w) {
    return ((a + off) * w + (b + off)) * w + (c + off);
  }
}
